steps.data:
{
  "$schema": "https://schemas.wp.org/trunk/theme.json",
  "version": 3,
  "settings": {
    "appearanceTools": false,
    "layout": {
      "contentSize": "1240px",
      "wideSize": "1240px"
    },
    "color": {
      "defaultPalette": false,
      "defaultGradients": false
    },
    "typography": {
      "defaultFontSizes": false
    }
  },
  "styles": {
    "spacing": {
      "blockGap": "0",
      "padding": {
        "top": "0",
        "bottom": "0",
        "left": "0",
        "right": "0"
      }
    },
    "color": {
      "background": "#ffffff",
      "text": "#1d1d1f"
    },
    "typography": {
      "fontFamily": "Inter, -apple-system, 'Noto Sans Thai', sans-serif"
    }
  },
  "customTemplates": [
    {
      "name": "page-plain",
      "title": "WIBWUB เต็มหน้า (ไม่มีหัวข้อ)",
      "postTypes": [
        "page"
      ]
    }
  ]
}

/* ============================================================
   WIBWUB Theme v2 — base.css
   Minimal luxury · Apple + Tesla · Inter · WIBWUB blue accent
   (ชื่อ class เดียวกับธีมเดิม เพื่อให้ Liquid ทุกหน้าทำงานต่อได้)
   ============================================================ */

*, *::before, *::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: var(--font-body, "Inter", -apple-system, BlinkMacSystemFont, "Noto Sans Thai", "Helvetica Neue", Arial, sans-serif);
  color: var(--color-text, #1d1d1f);
  background: var(--color-background, #ffffff);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img { max-width: 100%; height: auto; display: block; }

a { color: inherit; text-decoration: none; }

h1, h2, h3, h4 {
  font-family: var(--font-heading, "Inter", -apple-system, "Noto Sans Thai", sans-serif);
  color: var(--color-heading, #1d1d1f);
  font-weight: 700;
  letter-spacing: -0.022em;
  margin: 0;
  line-height: 1.08;
}

/* ---- Utilities ---- */
.page-width {
  max-width: var(--page-width, 1240px);
  margin-inline: auto;
  padding-inline: 22px;
}

.skip-link {
  position: absolute;
  left: -9999px; top: 0;
  background: #fff; padding: 10px 16px; z-index: 1000;
}
.skip-link:focus { left: 0; }

/* ---- Buttons: ขาวโปร่งแสง · hover ตัวอักษรน้ำเงิน ---- */
.btn {
  display: inline-block;
  background: rgba(255, 255, 255, 0.55);
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
  color: var(--color-heading, #1d1d1f);
  padding: 13px 30px;
  border: 1px solid rgba(0, 0, 0, 0.20);
  border-radius: var(--radius, 0);
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0;
  cursor: pointer;
  transition: color .2s ease, border-color .2s ease, background .2s ease, transform .15s ease;
}
.btn:hover {
  color: var(--color-accent, #0a1fe0);
  border-color: var(--color-accent, #0a1fe0);
  background: rgba(255, 255, 255, 0.85);
  transform: translateY(-1px);
}

/* ghost / secondary: ขอบดำ พื้นโปร่ง */
.btn--secondary {
  background: transparent;
  color: var(--color-heading, #1d1d1f);
  border: 1px solid rgba(0,0,0,.28);
}
.btn--secondary:hover { background: rgba(0,0,0,.04); box-shadow: none; }

/* น้ำเงิน = ลิงก์ */
.link-underline {
  display: inline-block;
  font-weight: 600;
  color: var(--color-accent, #0a1fe0);
  letter-spacing: 0;
}
.link-underline:hover { text-decoration: underline; text-underline-offset: 4px; }

.section-heading {
  font-size: clamp(30px, 5vw, 52px);
  font-weight: 700;
  letter-spacing: -0.025em;
  text-align: center;
}

/* ============================================================
   HEADER
   ============================================================ */
.site-header {
  background: rgba(255, 255, 255, 0.50);
  -webkit-backdrop-filter: saturate(180%) blur(22px);
  backdrop-filter: saturate(180%) blur(22px);
  border-bottom: 1px solid rgba(0, 0, 0, 0.05);
  position: sticky;
  top: 0;
  z-index: 100;
  transition: transform .35s ease, opacity .35s ease, background .2s ease;
  will-change: transform;
}
.site-header.is-hidden {
  transform: translateY(-100%);
  opacity: 0;
  pointer-events: none;
}
.site-header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-block: 6px;
}
.site-header__logo img { display: block; height: auto; width: auto; }
.site-header__logo-text {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 22px;
  letter-spacing: -0.02em;
  color: var(--color-heading, #1d1d1f);
}

.site-nav { display: none; }
.site-nav > ul { display: flex; gap: 30px; margin: 0; padding: 0; list-style: none; }
.site-nav > ul > li { position: relative; }
.site-nav a {
  font-size: 15px;
  font-weight: 500;
  color: var(--color-text, #1d1d1f);
  transition: color .2s ease;
}
.site-nav a:hover { color: var(--color-accent, #0a1fe0); }

/* ---- Dropdown หมวดสินค้า ---- */
.site-nav > ul > li.has-dropdown { padding-bottom: 16px; margin-bottom: -16px; }   /* ขยายพื้นที่ hover กันหลุด */
.nav-dropdown {
  display: block;
  position: absolute;
  top: 100%; left: 0;
  min-width: 210px;
  background: #fff;
  border: 1px solid #ececf0;
  box-shadow: 0 14px 34px rgba(0, 0, 0, 0.12);
  padding: 8px 0; margin: 0;
  list-style: none;
  z-index: 200;
  opacity: 0; visibility: hidden; transform: translateY(8px);
  transition: opacity .2s ease, transform .2s ease, visibility .2s;
}
.site-nav > ul > li.is-open > .nav-dropdown { opacity: 1; visibility: visible; transform: translateY(0); }
.nav-dropdown li { display: block; }
.nav-dropdown a {
  display: block; padding: 9px 22px; font-size: 14px; font-weight: 500;
  white-space: nowrap; color: var(--color-text, #1d1d1f);
}
.nav-dropdown a:hover { color: var(--color-accent, #0a1fe0); background: var(--color-surface, #f5f5f7); }

.site-header__icons { display: flex; align-items: center; gap: 20px; }
.site-header__icons a { display: inline-flex; color: var(--color-heading, #1d1d1f); transition: color .2s ease; }
.site-header__icons a:hover { color: var(--color-accent, #0a1fe0); }
.site-header__icons svg { width: 21px; height: 21px; }
.cart-count { font-size: 12px; vertical-align: super; margin-left: 2px; }

.nav-toggle { display: inline-flex; background: none; border: none; padding: 0; cursor: pointer; color: var(--color-heading); }
.nav-toggle svg { width: 26px; height: 26px; }

.mobile-nav { display: none; border-top: 1px solid #eee; padding: 12px 22px 20px; background: #fff; }
.mobile-nav.is-open { display: block; }
.mobile-nav ul { list-style: none; margin: 0; padding: 0; }
.mobile-nav li { border-bottom: 1px solid #f1f1f1; }
.mobile-nav a { display: block; padding: 14px 0; font-size: 17px; font-weight: 500; }

@media (min-width: 990px) {
  .site-nav { display: block; }
  .nav-toggle { display: none; }
  .mobile-nav { display: none !important; }
}

/* ============================================================
   HERO
   ============================================================ */
.hero {
  position: relative;
  display: flex;
  align-items: center;
  min-height: 62vh;
  color: #fff;
  overflow: hidden;
  margin-top: -44px;   /* ดันขึ้นไปอยู่หลัง header (โปร่งแสง) */
}
.hero--full { min-height: 118vh; }
.hero__media { position: absolute; inset: 0; z-index: 0; }
.hero__media img { width: 100%; height: 100%; object-fit: cover; }
.hero__overlay { position: absolute; inset: 0; z-index: 1; }
.hero__content {
  position: relative; z-index: 2;
  max-width: var(--page-width, 1240px);
  width: 100%; margin-inline: auto; padding: 48px 22px;
}
.hero__inner { max-width: 720px; }
.hero__text {
  color: #fff;
  font-size: clamp(40px, 7vw, 86px);
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.01em;
  line-height: 1.02;
  margin: 0 0 28px;
  max-width: 8em;
  text-shadow: 0 2px 30px rgba(0,0,0,.5), 0 1px 4px rgba(0,0,0,.4);
}
.hero__cta {
  display: inline-block;
  color: #fff;
  font-weight: 600;
  border-bottom: 1.5px solid rgba(255,255,255,.65);
  padding-bottom: 2px;
  transition: border-color .2s ease;
}
.hero__cta:hover { border-color: #fff; }

/* ---- Hero carousel (fade slides + nav + dots) ---- */
.hero-carousel { position: relative; }
.hero-slide { position: absolute; inset: 0; opacity: 0; visibility: hidden; transition: opacity .8s ease; display: flex; align-items: center; }
.hero-slide.is-active { opacity: 1; visibility: visible; }
.hero-nav {
  position: absolute; top: 50%; transform: translateY(-50%); z-index: 5;
  width: 48px; height: 48px; border-radius: 50%;
  border: 1px solid rgba(255,255,255,.6); background: rgba(0,0,0,.22);
  -webkit-backdrop-filter: blur(4px); backdrop-filter: blur(4px);
  color: #fff; font-size: 24px; line-height: 1; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  transition: background .2s, border-color .2s;
}
.hero-nav:hover { background: rgba(0,0,0,.5); border-color: #fff; }
.hero-nav--prev { left: clamp(16px, 3vw, 40px); }
.hero-nav--next { right: clamp(16px, 3vw, 40px); }
.hero-dots {
  position: absolute; left: 0; right: 0; bottom: clamp(40px, 8vh, 80px); z-index: 5;
  display: flex; gap: 10px; justify-content: center;
}
.hero-dots button {
  width: 10px; height: 10px; border-radius: 50%; border: none; padding: 0;
  background: rgba(255,255,255,.45); cursor: pointer; transition: background .2s, transform .2s;
}
.hero-dots button.is-active { background: #fff; transform: scale(1.25); }
@media (max-width: 600px) { .hero-nav { width: 40px; height: 40px; font-size: 20px; } }

/* ---- Home full-bleed image banners (ต่อจาก Hero) ---- */
.home-banners { display: flex; flex-direction: column; gap: 0; margin: 0; }
.home-banner { position: relative; display: block; width: 100%; height: 118vh; overflow: hidden; }
.home-banner img { width: 100%; height: 100%; object-fit: cover; display: block; }
.home-banner-pair { display: flex; gap: 0; width: 100%; height: 118vh; }
.home-banner-pair .home-banner-cell { position: relative; flex: 1 1 0; min-width: 0; overflow: hidden; }
.home-banner-pair .home-banner-cell img { width: 100%; height: 100%; object-fit: cover; display: block; }
@media (max-width: 600px) {
  .home-banner-pair { height: auto; flex-direction: column; }
  .home-banner-pair .home-banner-cell { aspect-ratio: 1 / 1; }
}

/* ---- SpaceX-style text overlay บนรูปแบนเนอร์ ---- */
.banner-overlay {
  position: absolute; inset: 0; z-index: 2;
  display: flex; flex-direction: column; align-items: center; justify-content: flex-end;
  text-align: center; padding: 0 24px clamp(64px, 12vh, 150px);
  color: #fff; pointer-events: none;
  background: linear-gradient(to top, rgba(0,0,0,0.72) 0%, rgba(0,0,0,0.28) 38%, rgba(0,0,0,0) 62%);
}
.banner-overlay--top { justify-content: flex-start; padding: clamp(96px, 16vh, 190px) 24px 0;
  background: linear-gradient(to bottom, rgba(0,0,0,0.70) 0%, rgba(0,0,0,0.24) 38%, rgba(0,0,0,0) 62%); }
.banner-overlay--middle { justify-content: center; padding-top: 0; padding-bottom: 0; }
.banner-overlay--right { align-items: flex-end; text-align: right; padding-left: clamp(24px, 6vw, 96px); padding-right: clamp(40px, 13vw, 230px);
  background: linear-gradient(to left, rgba(0,0,0,0.52) 0%, rgba(0,0,0,0.16) 42%, rgba(0,0,0,0) 64%); }
.banner-overlay--right .banner-overlay__actions { justify-content: flex-end; }
.banner-overlay--left { align-items: flex-start; text-align: left; padding-left: clamp(40px, 13vw, 230px); padding-right: clamp(24px, 6vw, 96px);
  background: linear-gradient(to right, rgba(0,0,0,0.52) 0%, rgba(0,0,0,0.16) 42%, rgba(0,0,0,0) 64%); }
.banner-overlay--left .banner-overlay__actions { justify-content: flex-start; }
/* ขนาดหัวเรื่อง */
.banner-overlay--sm .banner-overlay__title { font-size: clamp(22px, 2.8vw, 40px); }
.banner-overlay--lg .banner-overlay__title { font-size: clamp(34px, 5.2vw, 76px); }
.banner-overlay__eyebrow { font-size: clamp(11px, 0.85vw, 13px); font-weight: 600; letter-spacing: .28em; text-transform: uppercase; opacity: .85; margin-bottom: 14px; }
.banner-overlay__title { color: #fff; font-size: clamp(28px, 4vw, 58px); font-weight: 800; letter-spacing: .04em; line-height: 1.04; text-transform: uppercase; margin: 0; max-width: 14ch; text-shadow: 0 0 20px rgba(0,0,0,.85), 0 2px 30px rgba(0,0,0,.6), 0 1px 4px rgba(0,0,0,.5); }
.banner-overlay__sub { margin: 16px 0 0; font-size: clamp(14px, 1.15vw, 18px); font-weight: 400; letter-spacing: .01em; line-height: 1.5; max-width: 620px; opacity: .94; text-shadow: 0 1px 16px rgba(0,0,0,.4); }
.banner-overlay__actions { margin-top: 26px; display: flex; flex-wrap: wrap; gap: 14px; justify-content: center; pointer-events: auto; }
.banner-overlay__btn { display: inline-block; min-width: 168px; padding: 12px 26px; font-size: 12px; font-weight: 600; letter-spacing: .16em; text-transform: uppercase; text-decoration: none; transition: background .2s, color .2s, border-color .2s; }
.banner-overlay__btn--primary { background: rgba(255,255,255,0.92); color: #1d1d1f; border: 1px solid rgba(255,255,255,0.92); }
.banner-overlay__btn--primary:hover { background: #fff; color: var(--color-accent, #0a1fe0); }
.banner-overlay__btn--ghost { background: rgba(255,255,255,0.08); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px); color: #fff; border: 1px solid rgba(255,255,255,0.65); }
.banner-overlay__btn--ghost:hover { background: rgba(255,255,255,0.92); color: #1d1d1f; border-color: #fff; }
/* ป้ายเล็กมุมล่างซ้าย สำหรับรูปคู่ */
.banner-cell-label { position: absolute; inset: 0; z-index: 2; display: flex; flex-direction: column; justify-content: flex-end; align-items: flex-start;
  padding: 28px; color: #fff; pointer-events: none;
  background: linear-gradient(to top, rgba(0,0,0,0.55) 0%, rgba(0,0,0,0.05) 40%, rgba(0,0,0,0) 60%); }
.banner-cell-label__title { font-size: clamp(20px, 2vw, 30px); font-weight: 800; letter-spacing: .05em; text-transform: uppercase; text-shadow: 0 2px 20px rgba(0,0,0,.4); }
.banner-cell-label__sub { margin-top: 6px; font-size: clamp(12px, 1vw, 15px); opacity: .92; text-shadow: 0 1px 14px rgba(0,0,0,.45); }
.banner-cell-btn { pointer-events: auto; margin-top: 16px; display: inline-block; padding: 11px 22px;
  background: rgba(255,255,255,0.92); color: #1d1d1f; font-size: 12px; font-weight: 700;
  letter-spacing: .12em; text-transform: uppercase; text-decoration: none;
  transition: background .2s, color .2s; }
.banner-cell-btn:hover { background: #fff; color: var(--color-accent, #0a1fe0); }
@media (max-width: 600px) {
  .banner-overlay { padding-bottom: clamp(40px, 8vh, 72px); }
  .banner-cell-label { padding: 18px; }
}

/* ============================================================
   SECTIONS / PRODUCT GRID
   ============================================================ */
.section { padding-block: clamp(64px, 10vw, 120px); }
.section--surface { background: var(--color-surface, #f5f5f7); }
#services { scroll-margin-top: 90px; }
.section--tight { padding-block: clamp(36px, 6vw, 72px); }

.product-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 18px;
  margin-top: 48px;
}
@media (min-width: 750px) {
  .product-grid { grid-template-columns: repeat(4, 1fr); gap: 28px; }
}
/* การ์ดสินค้า — สไตล์ Pantone card (เหลี่ยม + ป้ายชื่อชิดซ้าย) */
.product-card {
  position: relative;
  text-align: left;
  padding: 0;
  border-radius: 0;                 /* คม ไม่มน */
  background: #fff;
  border: 1px solid #ececf0;
  overflow: hidden;
  transition: transform .2s ease, box-shadow .25s ease;
}
.product-card:hover { transform: translateY(-4px); box-shadow: 0 16px 44px rgba(0,0,0,.12); }
.product-card__media {
  aspect-ratio: 1 / 1;
  background: var(--color-surface, #f5f5f7);
  overflow: hidden;
  border-radius: 0;
}
.product-card__media img { width: 100%; height: 100%; object-fit: cover; transition: transform .5s ease; }
.product-card:hover .product-card__media img { transform: scale(1.05); }
/* โลโก้แบรนด์ มุมขวาล่างของการ์ด (ข้างราคา) */
.product-card::after {
  content: "";
  position: absolute; right: 16px; bottom: 16px;
  width: 72px; height: 20px;
  background: url("logo-gray.png") no-repeat center right;
  background-size: contain;
  pointer-events: none;
}

/* ป้ายแบบ Pantone: ชื่อ / ราคา */
.product-card__title {
  padding: 15px 16px 0;
  font-size: 15px; font-weight: 600;
  color: var(--color-heading); line-height: 1.35;
}
.product-card__price {
  padding: 6px 16px 16px;
  font-size: 14px; letter-spacing: 0.03em; color: #6e6e73;
}

.empty-state {
  margin-top: 36px; text-align: center; color: #86868b;
  border: 1px dashed #d2d2d7; border-radius: 0; padding: 64px 20px;
}

/* ============================================================
   SERVICES
   ============================================================ */
.services__intro {
  max-width: 720px; margin: 22px auto 0; text-align: center;
  color: #6e6e73; font-size: 18px;
}
.services__grid {
  display: grid; grid-template-columns: 1fr; gap: 48px; margin-top: 64px;
}
@media (min-width: 750px) { .services__grid { grid-template-columns: repeat(3, 1fr); } }
.service { text-align: center; }
.service__icon {
  width: 64px; height: 64px; margin: 0 auto 22px;
  display: flex; align-items: center; justify-content: center;
  color: var(--color-accent, #0a1fe0);
}
.service__icon img { width: 100%; height: 100%; object-fit: contain; }
.service__title { font-size: 21px; font-weight: 600; letter-spacing: -0.01em; margin-bottom: 10px; }
.service__text { color: #6e6e73; margin: 0; }

/* ============================================================
   COLLECTION PAGE
   ============================================================ */
.breadcrumb { padding: 22px 0 0; font-size: 13px; color: #86868b; }
.breadcrumb a { color: #86868b; }
.breadcrumb a:hover { color: var(--color-accent); }
.breadcrumb span { margin: 0 8px; color: #c7c7cc; }

/* Banner — Pantone swatch card (มุมเหลี่ยม, สีสด) */
.collection-banner {
  margin-top: 18px;
  overflow: hidden;
  border-radius: 0;           /* คม ไม่มน */
}
.collection-banner img {
  width: 100%; height: auto; max-height: 380px; object-fit: cover; display: block;
}

.pantone-card {
  --swatch: #00AEEF;
  display: flex;
  flex-direction: column;
  aspect-ratio: 1470 / 360;
  max-height: 380px;
  background: #fff;
  box-shadow: 0 1px 0 rgba(0,0,0,.05);
}
.pantone-card__swatch {
  flex: 1;
  background-color: var(--swatch);
  /* แสงเฉียงบางๆ ให้ดูสดมีมิติ — ยังคงความ "Pantone" */
  background-image: linear-gradient(135deg, rgba(255,255,255,.16), rgba(0,0,0,.05) 70%);
}
.pantone-card__label {
  background: #fff;
  padding: clamp(12px, 1.6vw, 20px) clamp(16px, 2vw, 28px);
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.pantone-card__brand {
  font-size: 12px; font-weight: 700; letter-spacing: 0.10em;
  color: var(--color-heading, #1d1d1f); text-transform: uppercase;
}
.pantone-card__name {
  font-size: clamp(18px, 2.6vw, 30px); font-weight: 700;
  letter-spacing: -0.02em; color: var(--color-heading, #1d1d1f); line-height: 1.05;
}
.pantone-card__code {
  font-size: 12px; letter-spacing: 0.06em; color: #6e6e73; margin-top: 2px;
}

.collection-title {
  font-size: clamp(28px, 4vw, 40px);
  font-weight: 700;
  letter-spacing: -0.025em;
  margin: 34px 0 28px;
}

.collection-layout { display: grid; grid-template-columns: 1fr; gap: 36px; }
@media (min-width: 990px) { .collection-layout { grid-template-columns: 1fr; } }

.collection-filters__title {
  font-size: 17px; font-weight: 600; color: var(--color-heading);
  border-bottom: 1px solid #e5e5ea; padding-bottom: 14px; margin-bottom: 12px;
}
.collection-filters ul { list-style: none; margin: 0; padding: 0; }
.collection-filters a {
  display: block; padding: 10px 0; font-size: 15px; color: #1d1d1f;
  transition: color .2s ease;
}
.collection-filters a:hover,
.collection-filters a.is-active { color: var(--color-accent); font-weight: 500; }
.filter-menu a.is-active { text-decoration: underline; text-underline-offset: 3px; }

/* ---- กรองตาม (facets) ---- */
.facets { margin-top: 40px; }
.facet { border-top: 1px solid #ececf0; }
.facet:first-of-type { border-top: 0; }
.facet__summary {
  list-style: none;
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 0; cursor: pointer;
  font-size: 15px; font-weight: 600; color: var(--color-heading);
}
.facet__summary::-webkit-details-marker { display: none; }
.facet__toggle { position: relative; width: 13px; height: 13px; flex-shrink: 0; }
.facet__toggle::before,
.facet__toggle::after {
  content: ""; position: absolute; background: var(--color-heading);
}
.facet__toggle::before { top: 6px; left: 0; width: 13px; height: 1.5px; }       /* แนวนอน */
.facet__toggle::after  { left: 6px; top: 0; width: 1.5px; height: 13px; }        /* แนวตั้ง (= เครื่องหมาย +) */
.facet[open] .facet__toggle::after { display: none; }                            /* เปิด = เหลือ − */

.facet__list { list-style: none; margin: 0 0 16px; padding: 0; }
.facet__item {
  display: flex; align-items: center; gap: 12px;
  padding: 6px 0; cursor: pointer;
  font-size: 15px; color: var(--color-text);
}
.facet__item input { position: absolute; opacity: 0; width: 0; height: 0; }
.facet__box {
  width: 18px; height: 18px; flex-shrink: 0;
  border: 1.5px solid #c7c7cc; border-radius: 0;     /* checkbox เหลี่ยม */
  position: relative; transition: border-color .15s ease, background .15s ease;
}
.facet__item:hover .facet__box { border-color: #9a9aa0; }
.facet__item input:checked + .facet__box {
  background: var(--color-accent, #0a1fe0);
  border-color: var(--color-accent, #0a1fe0);
}
.facet__item input:checked + .facet__box::after {
  content: ""; position: absolute; left: 5px; top: 1px;
  width: 5px; height: 10px; border: solid #fff; border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}
.facet__item input:focus-visible + .facet__box { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.facet__item input:disabled ~ .facet__label { color: #c7c7cc; }
.facet__label { line-height: 1.3; }

.collection-toolbar {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 26px; font-size: 14px; color: #6e6e73;
}
.collection-toolbar select {
  border: 1px solid #d2d2d7; padding: 9px 14px; font-size: 14px;
  background: #fff; border-radius: 0; font-family: inherit;
}

.collection-layout .product-grid { margin-top: 0; grid-template-columns: repeat(2, 1fr); }
@media (min-width: 990px) { .collection-layout .product-grid { grid-template-columns: repeat(3, 1fr); } }

/* ============================================================
   PRODUCT PAGE
   ============================================================ */
.product {
  display: grid; grid-template-columns: 1fr; gap: 36px;
  padding-block: clamp(28px, 4vw, 56px);
}
@media (min-width: 850px) { .product { grid-template-columns: 1fr 1fr; gap: 64px; align-items: start; } }
.product__gallery-main {
  aspect-ratio: 1 / 1; background: var(--color-surface, #f5f5f7);
  overflow: hidden; border-radius: 0;
}
.product__gallery-main img { width: 100%; height: 100%; object-fit: cover; }
.product__thumbs { display: flex; gap: 12px; margin-top: 14px; flex-wrap: wrap; }
.product__thumbs button {
  width: 72px; height: 72px; padding: 0; border: 1px solid #e3e3e8;
  background: var(--color-surface, #f5f5f7); cursor: pointer; overflow: hidden; border-radius: 0;
}
.product__thumbs button.is-active { border-color: var(--color-accent); }
.product__thumbs img { width: 100%; height: 100%; object-fit: cover; }

.product__title {
  font-size: clamp(26px, 3vw, 34px);
  font-weight: 700; letter-spacing: -0.022em;
  color: var(--color-heading); line-height: 1.15;
}
.product__price { font-size: 22px; color: var(--color-heading); margin: 16px 0 28px; font-weight: 500; }
.product__price .compare { color: #aeaeb2; text-decoration: line-through; margin-left: 10px; font-size: 17px; }

.product__qty-label { display: block; font-size: 14px; color: #6e6e73; margin-bottom: 8px; }
.qty-stepper { display: inline-flex; align-items: center; border: 1px solid #d2d2d7; margin-bottom: 22px; border-radius: 0; overflow: hidden; }
.qty-stepper button { width: 44px; height: 44px; background: #fff; border: none; font-size: 18px; cursor: pointer; color: var(--color-text); }
.qty-stepper input {
  width: 54px; height: 44px; text-align: center; border: none;
  border-left: 1px solid #eee; border-right: 1px solid #eee; font-size: 15px; -moz-appearance: textfield;
}
.qty-stepper input::-webkit-outer-spin-button,
.qty-stepper input::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }

.product__form .btn { display: block; width: 100%; text-align: center; margin-bottom: 12px; }

.product__share { display: flex; gap: 18px; margin-top: 26px; }
.product__share a { color: #86868b; transition: color .2s ease; }
.product__share a:hover { color: var(--color-accent); }
.product__share svg { width: 22px; height: 22px; }

.product__description { margin-top: 22px; color: #6e6e73; line-height: 1.75; }
.product__description h2 { font-size: 18px; margin-bottom: 8px; color: var(--color-heading); }

.pagination { margin-top: 48px; text-align: center; }
.pagination a, .pagination span { display: inline-block; padding: 8px 14px; margin: 0 2px; font-size: 15px; color: #1d1d1f; }
.pagination span[aria-current] { font-weight: 700; color: var(--color-accent); }

/* ============================================================
   CONTENT PAGES (Partners / Stores / generic)
   ============================================================ */
.page-hero { text-align: center; padding-block: clamp(56px, 8vw, 96px) 10px; }
.page-hero__title { font-size: clamp(34px, 6vw, 60px); font-weight: 700; letter-spacing: -0.03em; }
.page-hero__divider { width: 44px; height: 3px; border-radius: 0; background: var(--color-accent, #0a1fe0); margin: 22px auto; }
.page-hero__subtitle { color: #6e6e73; max-width: 640px; margin: 0 auto; font-size: 18px; }

.partners-grid { display: grid; grid-template-columns: 1fr; gap: 32px; margin-top: 60px; }
@media (min-width: 750px) { .partners-grid { grid-template-columns: repeat(3, 1fr); } }
.partner-card__media { aspect-ratio: 1 / 1; background: var(--color-surface, #f5f5f7); overflow: hidden; border-radius: 0; }
.partner-card__media img { width: 100%; height: 100%; object-fit: cover; }
.partner-card__name { text-align: center; margin-top: 16px; font-size: 16px; font-weight: 500; }

.stores-intro { color: #6e6e73; margin-bottom: 8px; font-size: 17px; }
.stores-divider { height: 1px; background: #e5e5ea; margin: 26px 0 40px; }
.stores-grid { display: grid; grid-template-columns: 1fr; gap: 40px; }
@media (min-width: 750px) { .stores-grid { grid-template-columns: repeat(3, 1fr); } }
.store__name { font-size: 19px; font-weight: 600; color: var(--color-heading); margin-bottom: 12px; }
.store__detail { white-space: pre-line; color: #6e6e73; line-height: 1.75; }

/* ---- About page ---- */
.about-eyebrow {
  text-align: center; font-size: 12px; font-weight: 700; letter-spacing: 0.18em;
  text-transform: uppercase; color: var(--color-accent, #0a1fe0); margin-bottom: 14px;
}
.about-intro {
  max-width: 760px; margin: 0 auto; text-align: center;
  font-size: clamp(18px, 2.2vw, 22px); line-height: 1.6; color: #1d1d1f;
}
.about-image {
  margin-top: clamp(40px, 6vw, 72px);
  aspect-ratio: 16 / 7; max-height: 520px; overflow: hidden; background: var(--color-surface, #f5f5f7);
}
.about-image img { width: 100%; height: 100%; object-fit: cover; }

.stats-row {
  display: grid; grid-template-columns: 1fr; gap: 1px;
  margin-top: clamp(48px, 6vw, 80px); background: #ececf0;
  border: 1px solid #ececf0;
}
@media (min-width: 700px) { .stats-row { grid-template-columns: repeat(3, 1fr); } }
.stat { background: #fff; padding: 36px 24px; text-align: center; }
.stat__num { font-size: clamp(34px, 5vw, 52px); font-weight: 800; letter-spacing: -0.03em; color: var(--color-heading, #1d1d1f); line-height: 1; }
.stat__label { margin-top: 10px; font-size: 14px; color: #6e6e73; }

.values-grid { display: grid; grid-template-columns: 1fr; gap: 28px; margin-top: clamp(48px, 6vw, 80px); }
@media (min-width: 750px) { .values-grid { grid-template-columns: repeat(3, 1fr); } }
.value {
  background: var(--color-surface, #f5f5f7); padding: 32px 28px; border: 1px solid #ececf0;
}
.value__title { font-size: 19px; font-weight: 700; letter-spacing: -0.01em; margin-bottom: 8px; color: var(--color-heading); }
.value__title::before {
  content: ""; display: block; width: 28px; height: 4px; background: var(--color-accent, #0a1fe0); margin-bottom: 16px;
}
.value__text { color: #6e6e73; margin: 0; line-height: 1.65; }

/* ---- Services page ---- */
.svc-grid { display: grid; grid-template-columns: 1fr; gap: 24px; margin-top: clamp(40px, 5vw, 64px); }
@media (min-width: 750px) { .svc-grid { grid-template-columns: repeat(3, 1fr); } }
.svc-card { background: #fff; border: 1px solid #ececf0; overflow: hidden; display: flex; flex-direction: column; transition: transform .2s ease, box-shadow .25s ease; }
.svc-card:hover { transform: translateY(-4px); box-shadow: 0 16px 44px rgba(0,0,0,.10); }
.svc-card__media { aspect-ratio: 4 / 3; background: var(--color-surface, #f5f5f7); overflow: hidden; }
.svc-card__media img { width: 100%; height: 100%; object-fit: cover; }
.svc-card__body { padding: 26px; display: flex; flex-direction: column; gap: 10px; flex: 1; }
.svc-card__no { font-size: 12px; font-weight: 700; letter-spacing: .14em; color: var(--color-accent, #0a1fe0); }
.svc-card__title { font-size: 21px; font-weight: 700; letter-spacing: -.01em; color: var(--color-heading); }
.svc-card__text { color: #6e6e73; margin: 0; line-height: 1.65; flex: 1; }
.svc-card__cta { color: var(--color-accent, #0a1fe0); font-weight: 600; margin-top: 8px; }

/* ---- Community page ---- */
.community-grid { display: grid; grid-template-columns: 1fr; gap: 24px; margin-top: clamp(40px, 5vw, 64px); }
@media (min-width: 750px) { .community-grid { grid-template-columns: repeat(3, 1fr); } }
.post-card { background: #fff; border: 1px solid #ececf0; overflow: hidden; transition: transform .2s ease, box-shadow .25s ease; }
.post-card:hover { transform: translateY(-4px); box-shadow: 0 16px 44px rgba(0,0,0,.10); }
.post-card__media { aspect-ratio: 3 / 2; background: var(--color-surface, #f5f5f7); overflow: hidden; }
.post-card__media img { width: 100%; height: 100%; object-fit: cover; }
.post-card__body { padding: 20px 20px 24px; }
.post-card__tag { font-size: 11px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--color-accent, #0a1fe0); }
.post-card__title { font-size: 17px; font-weight: 600; line-height: 1.4; margin: 8px 0 6px; color: var(--color-heading); }
.post-card__date { font-size: 13px; color: #86868b; }

.rte { line-height: 1.75; color: #1d1d1f; }
.rte h1, .rte h2 { margin: 1em 0 .4em; }
.rte p { margin: 0 0 1em; }
.rte a { color: var(--color-accent); text-decoration: underline; }

/* ============================================================
   CART
   ============================================================ */
.cart { padding-block: clamp(28px, 4vw, 56px); }
.cart__title { font-size: clamp(30px, 4vw, 44px); font-weight: 700; letter-spacing: -0.025em; margin-bottom: 32px; }
.cart__row {
  display: grid; grid-template-columns: 88px 1fr auto; gap: 18px; align-items: center;
  padding: 20px 0; border-bottom: 1px solid #e5e5ea;
}
.cart__row img { width: 88px; height: 88px; object-fit: cover; background: var(--color-surface); border-radius: 0; }
.cart__name { font-size: 15px; font-weight: 500; color: var(--color-heading); }
.cart__footer { display: flex; justify-content: space-between; align-items: center; margin-top: 30px; flex-wrap: wrap; gap: 16px; }
.cart__total { font-size: 22px; font-weight: 600; color: var(--color-heading); }
.cart--empty { text-align: center; padding: 90px 20px; color: #86868b; }

/* ============================================================
   FOOTER
   ============================================================ */
/* Footer — โปร่งแสงเหมือน header (ขาว 52% + เบลอ, ตัวอักษรเข้ม) */
.site-footer {
  position: relative;
  background: rgba(255, 255, 255, 0.50);
  -webkit-backdrop-filter: saturate(180%) blur(22px);
  backdrop-filter: saturate(180%) blur(22px);
  border-top: 1px solid rgba(0, 0, 0, 0.05);
  color: var(--color-heading, #1d1d1f);
  overflow: hidden;
}
.footer-watermark { display: none; }   /* ตัดลายน้ำ WIBWUB ออก */
.site-footer__grid {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 12px 24px;
  padding: clamp(4px, 0.6vw, 7px) 0;
}
@media (min-width: 800px) {
  .site-footer__grid { grid-template-columns: 1.4fr 1fr 1fr 1fr; gap: 24px; }
}
.footer-brand { grid-column: 1 / -1; }
@media (min-width: 800px) { .footer-brand { grid-column: auto; } }
.footer-logo { width: 98px; }

.footer-col__title {
  font-size: 13px; font-weight: 700; letter-spacing: 0.12em;
  text-transform: uppercase; color: var(--color-heading, #1d1d1f); margin-bottom: 0;
  transition: color .2s ease;
}
a.footer-col__title:hover { color: var(--color-accent, #0a1fe0); }

/* หน้าแรก: footer ลอยทับรูปล่างสุด */
.site-footer--overlap,
.template-index .site-footer { margin-top: -44px; position: relative; z-index: 5; }
.footer-col a {
  display: block;
  color: rgba(0, 0, 0, 0.6);
  font-size: 14px; line-height: 1.3; padding: 2.5px 0;
  transition: color .2s ease;
}
.footer-col a:hover { color: var(--color-accent, #0a1fe0); }

.site-footer__bottom {
  position: relative;
  z-index: 2;
  border-top: 1px solid rgba(0, 0, 0, 0.08);
  padding: 10px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  font-size: 13px;
  color: rgba(0, 0, 0, 0.55);
}
.footer-legal a { color: rgba(0, 0, 0, 0.6); margin-left: 24px; transition: color .2s ease; }
.footer-legal a:first-child { margin-left: 0; }
.footer-legal a:hover { color: var(--color-accent, #0a1fe0); }
@media (max-width: 560px) {
  .footer-legal a { margin-left: 16px; }
}

/* ============================================================
   SHOP LANDING — Hero carousel + Browse by category + Trust bar
   ============================================================ */
.shop-hero{
  display:grid; grid-template-columns:0.82fr 1.4fr; gap:28px;
  background:linear-gradient(135deg,#f4f5f9 0%,#e9ebf2 60%,#eef0f6 100%);
  border-radius:0; padding:36px 40px; margin:22px 0 44px; overflow:hidden; position:relative;
}
.shop-hero::before{content:"";position:absolute;width:520px;height:520px;right:-160px;top:-160px;
  background:radial-gradient(circle at 30% 30%,rgba(10,31,224,.06),transparent 70%);border-radius:50%;}
.shop-hero__side{display:flex;flex-direction:column;justify-content:center;position:relative;z-index:2}
.shop-hero__crumb{font-size:11px;letter-spacing:.18em;color:#8a8f9a;text-transform:uppercase;font-weight:600;margin-bottom:16px}
.shop-hero__side h1{font-size:clamp(26px,3vw,40px);font-weight:800;letter-spacing:-.01em;line-height:1.05;text-transform:uppercase;color:#0c1024}
.shop-hero__side p{margin:12px 0 22px;color:#6e727d;font-size:14px}
.shop-hero__pill{align-self:flex-start;display:inline-flex;align-items:center;gap:10px;border:1.5px solid #0c1024;border-radius:999px;
  padding:11px 22px;font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#0c1024;transition:.2s}
.shop-hero__pill:hover{background:#0c1024;color:#fff}
.shop-hero__stage{position:relative;z-index:2;overflow:hidden}
.shop-hero__track{display:flex;transition:transform .55s cubic-bezier(.7,0,.2,1)}
.shop-slide{min-width:100%;display:grid;grid-template-columns:1fr 1fr;gap:20px;align-items:center}
.shop-slide__img{aspect-ratio:1/1;max-height:340px;border-radius:0;overflow:hidden;box-shadow:0 20px 44px rgba(12,16,36,.16)}
.shop-slide__img img{width:100%;height:100%;object-fit:cover}
.shop-slide__info{display:flex;flex-direction:column}
.shop-slide__info .eyebrow{font-size:12px;font-weight:800;letter-spacing:.14em;color:var(--color-accent,#0a1fe0);text-transform:uppercase}
.shop-slide__info h2{font-size:clamp(30px,3.4vw,52px);font-weight:800;letter-spacing:-.01em;line-height:1;text-transform:uppercase;color:#0c1024;margin:8px 0 4px}
.shop-slide__info .sub{font-size:13px;font-weight:700;letter-spacing:.1em;color:#3a3f4a;text-transform:uppercase}
.shop-slide__info .desc{margin:14px 0 16px;color:#6e727d;font-size:13.5px;line-height:1.55;max-width:320px}
.shop-slide__info .price{font-size:26px;font-weight:800;color:#0c1024}
.shop-hero__nav{display:flex;align-items:center;gap:14px;margin-top:22px}
.shop-hero__nav .prog{font-size:13px;font-weight:700;color:#0c1024;font-variant-numeric:tabular-nums}
.shop-hero__nav .bar{flex:0 0 90px;height:2px;background:#cfd3dd;position:relative;overflow:hidden}
.shop-hero__nav .bar i{position:absolute;left:0;top:0;height:100%;background:#0c1024;transition:width .45s}
.shop-hero__nav .tot{font-size:13px;color:#9aa0ac;font-weight:600}
.shop-hero__nav .sp{flex:1}
.shop-hero__btn{width:42px;height:42px;border-radius:50%;border:1.5px solid #c7ccd6;background:#fff;color:#0c1024;
  font-size:18px;display:grid;place-items:center;cursor:pointer;transition:.2s}
.shop-hero__btn:hover{background:#0c1024;color:#fff;border-color:#0c1024}

/* Browse by category */
.cat-section{margin:8px 0 40px}
.cat-head{display:flex;align-items:baseline;gap:12px;margin-bottom:18px}
.cat-head h2{font-size:20px;font-weight:800;letter-spacing:.01em;text-transform:uppercase;color:#0c1024}
.cat-head span{font-size:13px;color:#8a8f9a}
.cat-grid{display:flex;gap:16px;overflow-x:auto;overflow-y:hidden;scroll-snap-type:x proximity;
  padding-bottom:10px;scrollbar-width:thin;scrollbar-color:#c9cede transparent}
.cat-grid::-webkit-scrollbar{height:7px}
.cat-grid::-webkit-scrollbar-thumb{background:#cfd3dd;border-radius:10px}
.cat-card{position:relative;flex:0 0 clamp(152px,15vw,190px);scroll-snap-align:start;
  display:flex;flex-direction:column;border-radius:0;padding:14px;
  text-decoration:none;transition:transform .2s ease,box-shadow .25s ease;min-height:230px}
.cat-card:hover{transform:translateY(-4px);box-shadow:0 16px 36px rgba(12,16,36,.12)}
.cat-card__thumb{border-radius:0;overflow:hidden;aspect-ratio:1/1;background:rgba(255,255,255,.45)}
.cat-card__thumb img{width:100%;height:100%;object-fit:cover}
.cat-card__name{margin-top:12px;font-size:13px;font-weight:800;letter-spacing:.03em;text-transform:uppercase;color:#0c1024;line-height:1.2}
.cat-card__count{font-size:11.5px;color:#5a5f6a;margin-top:3px}
.cat-card__arrow{position:absolute;right:14px;bottom:14px;width:30px;height:30px;border-radius:50%;
  background:rgba(255,255,255,.7);display:grid;place-items:center;font-size:14px;color:#0c1024;transition:.2s}
.cat-card:hover .cat-card__arrow{background:#0c1024;color:#fff}
.cat-blue{background:linear-gradient(165deg,#e8f0ff,#cfe0ff)}
.cat-mint{background:linear-gradient(165deg,#e2f7f0,#c6ede2)}
.cat-amber{background:linear-gradient(165deg,#fff6da,#fbe6a6)}
.cat-peach{background:linear-gradient(165deg,#ffeede,#ffd6bd)}
.cat-green{background:linear-gradient(165deg,#e9f7e2,#cfeec2)}
.cat-pink{background:linear-gradient(165deg,#ffe9f1,#ffcfe1)}
.cat-cyan{background:linear-gradient(165deg,#e3f4ff,#c6e6ff)}
.cat-purple{background:linear-gradient(165deg,#efe9ff,#dccdff)}
.cat-lime{background:linear-gradient(165deg,#f1f7db,#e0edac)}

/* Trust bar */
.trust-bar{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;border:1px solid #e6e8ef;border-radius:16px;
  padding:20px 8px;margin:0 0 46px}
.trust-item{display:flex;align-items:center;gap:13px;justify-content:center;padding:4px 12px;border-right:1px solid #eef0f5}
.trust-item:last-child{border-right:none}
.trust-item svg{width:26px;height:26px;stroke:var(--color-accent,#0a1fe0);flex:0 0 auto}
.trust-item b{display:block;font-size:12.5px;font-weight:800;letter-spacing:.03em;color:#0c1024;text-transform:uppercase}
.trust-item span{font-size:11.5px;color:#7a7f8a}

@media(max-width:860px){
  .shop-hero{grid-template-columns:1fr;padding:26px 22px}
  .shop-slide{grid-template-columns:1fr;text-align:left}
  .shop-slide__img{max-height:240px}
  .cat-grid{grid-template-columns:repeat(3,1fr)}
  .trust-bar{grid-template-columns:1fr 1fr;gap:14px 0}
  .trust-item:nth-child(2){border-right:none}
}
@media(max-width:520px){
  .cat-grid{grid-template-columns:1fr 1fr}
  .trust-bar{grid-template-columns:1fr}.trust-item{border-right:none;justify-content:flex-start}
}

/* ===== ABOUT INTRO — WHO WE ARE (contained + square image) ===== */
.home-about{
  position:relative; overflow:hidden;
  background:linear-gradient(180deg,#eef0f8 0%,#e8ebf6 100%);
