/* PREVIEW ONLY — dropdown หมวดสินค้า (hover ค้าง ~0.45 วิ) + auto-hide header */
(function () {
  document.querySelectorAll('.site-nav [data-dropdown]').forEach(function (li) {
    var openT, closeT;
    li.addEventListener('mouseenter', function () {
      clearTimeout(closeT);
      openT = setTimeout(function () { li.classList.add('is-open'); }, 450);
    });
    li.addEventListener('mouseleave', function () {
      clearTimeout(openT);
      closeT = setTimeout(function () { li.classList.remove('is-open'); }, 150);
    });
  });

  // Auto-hide: เลื่อนลงสะสม ~300px ค่อยซ่อน / เลื่อนขึ้น = โผล่ทันที
  var header = document.querySelector('.site-header');
  if (header) {
    var lastY = window.pageYOffset, downAcc = 0;
    var HIDE_AFTER = 300, TOP = 100;
    window.addEventListener('scroll', function () {
      var y = window.pageYOffset, delta = y - lastY;
      if (y <= TOP) { header.classList.remove('is-hidden'); downAcc = 0; }
      else if (delta > 0) { downAcc += delta; if (downAcc > HIDE_AFTER) header.classList.add('is-hidden'); }
      else if (delta < 0) { header.classList.remove('is-hidden'); downAcc = 0; }
      lastY = y;
    }, { passive: true });
  }
})();

/* ===== Shop hero carousel ===== */
(function(){
  var track=document.querySelector('[data-track]'); if(!track) return;
  var slides=track.children, n=slides.length, i=0;
  var prog=document.querySelector('[data-prog]'), bar=document.querySelector('[data-bar]');
  var prev=document.querySelector('[data-prev]'), next=document.querySelector('[data-next]');
  function go(k){ i=(k+n)%n; track.style.transform='translateX('+(-100*i)+'%)';
    if(prog) prog.textContent=('0'+(i+1)).slice(-2);
    if(bar) bar.style.width=((i+1)/n*100)+'%'; }
  if(prev) prev.addEventListener('click',function(){go(i-1);reset();});
  if(next) next.addEventListener('click',function(){go(i+1);reset();});
  var timer=setInterval(function(){go(i+1);},5500);
  function reset(){ clearInterval(timer); timer=setInterval(function(){go(i+1);},5500); }
  go(0);
})();

/* ===== Hero carousel (fade + auto 5s + arrows + dots) ===== */
(function(){
  var hero=document.querySelector('[data-hero]'); if(!hero) return;
  var slides=[].slice.call(hero.querySelectorAll('.hero-slide')); if(slides.length<2) return;
  var dotsWrap=hero.querySelector('[data-hero-dots]');
  var prev=hero.querySelector('[data-hero-prev]'), next=hero.querySelector('[data-hero-next]');
  var i=0, timer;
  var dots=slides.map(function(_,k){
    var b=document.createElement('button'); b.setAttribute('aria-label','สไลด์ '+(k+1));
    b.addEventListener('click',function(){ go(k); reset(); });
    if(dotsWrap) dotsWrap.appendChild(b); return b;
  });
  function go(k){
    i=(k+slides.length)%slides.length;
    slides.forEach(function(s,n){ s.classList.toggle('is-active', n===i); });
    dots.forEach(function(d,n){ d.classList.toggle('is-active', n===i); });
  }
  if(prev) prev.addEventListener('click',function(){ go(i-1); reset(); });
  if(next) next.addEventListener('click',function(){ go(i+1); reset(); });
  function reset(){ clearInterval(timer); timer=setInterval(function(){ go(i+1); },10000); }
  go(0); reset();
})();

/* ===== HOME ABOUT SLIDER (Who We Are / Brand Essence) — ลูกศร + จุด + ปัด ===== */
(function(){
  var root = document.querySelector('[data-about-slider]');
  if(!root) return;
  var track  = root.querySelector('.about-slider__track');
  var slides = root.querySelectorAll('.about-slide');
  var dotsWrap = root.querySelector('[data-about-dots]');
  var prev = root.querySelector('.about-slider__arrow--prev');
  var next = root.querySelector('.about-slider__arrow--next');
  var n = slides.length, i = 0, dots = [];
  if(n < 2){ if(prev)prev.style.display='none'; if(next)next.style.display='none'; return; }
  for(var k=0;k<n;k++){ (function(k){
    var d = document.createElement('button');
    d.type='button'; d.className='about-slider__dot';
    d.setAttribute('aria-label','สไลด์ '+(k+1));
    d.addEventListener('click', function(){ go(k); });
    dotsWrap.appendChild(d); dots.push(d);
  })(k); }
  function render(){
    track.style.transform = 'translateX(-'+(i*100)+'%)';
    dots.forEach(function(d,idx){ d.classList.toggle('is-active', idx===i); });
  }
  function go(x){ i = (x % n + n) % n; render(); }
  if(prev) prev.addEventListener('click', function(){ go(i-1); });
  if(next) next.addEventListener('click', function(){ go(i+1); });
  /* ปัดซ้าย/ขวาบนมือถือ */
  var sx=0, sy=0, tracking=false;
  root.addEventListener('touchstart', function(e){ sx=e.touches[0].clientX; sy=e.touches[0].clientY; tracking=true; }, {passive:true});
  root.addEventListener('touchend', function(e){
    if(!tracking) return; tracking=false;
    var dx=e.changedTouches[0].clientX-sx, dy=e.changedTouches[0].clientY-sy;
    if(Math.abs(dx)>50 && Math.abs(dx)>Math.abs(dy)){ go(dx<0 ? i+1 : i-1); }
  }, {passive:true});
  render();
})();

