    var item = document.createElement('li'); var link = a.cloneNode(true); item.appendChild(link);
    var sub = li.querySelector(':scope > ul');
    if (sub) { var s = document.createElement('ul'); s.style.cssText = 'padding:0 0 8px 14px';
      [].forEach.call(sub.querySelectorAll('a'), function(x){ var l = document.createElement('li'); l.style.borderBottom='0'; var c = x.cloneNode(true); c.style.cssText='padding:8px 0;font-size:15px;font-weight:400;color:#555'; l.appendChild(c); s.appendChild(l); });
      item.appendChild(s); }
    ul.appendChild(item);
  });
  nav.appendChild(ul); header.appendChild(nav);
  btn.addEventListener('click', function(){ nav.classList.toggle('is-open'); });
})();

(function(){var r=document.querySelector('[data-wbfab]');if(!r)return;var b=r.querySelector('.wbfab__btn');
function set(o){r.classList.toggle('is-open',o);b.setAttribute('aria-expanded',o?'true':'false');}
b.addEventListener('click',function(e){e.stopPropagation();set(!r.classList.contains('is-open'));});
document.addEventListener('click',function(e){if(!r.contains(e.target))set(false);});
document.addEventListener('keydown',function(e){if(e.key==='Escape')set(false);});})();

:root{
  --color-text:#1D1D1F;--color-heading:#1D1D1F;--color-background:#fff;--color-surface:#F5F5F7;
  --color-accent:#0A1FE0;--color-button:#1D1D1F;--color-button-text:#fff;
  --page-width:1240px;--radius:0;
  --font-heading:"Inter",-apple-system,"Noto Sans Thai",sans-serif;
  --font-body:"Inter",-apple-system,"Noto Sans Thai",sans-serif;
}
.hero__media.real{background:#1c1c1c var(--wb-hero-img) center/cover no-repeat;}
body{background:#fff;}

.wbfab{position:fixed;right:20px;bottom:calc(20px + env(safe-area-inset-bottom));z-index:60;display:flex;flex-direction:column;align-items:flex-end;gap:12px;font-family:inherit}
.wbfab__btn{position:relative;display:inline-flex;align-items:center;gap:10px;height:52px;padding:0 22px 0 16px;border:0;border-radius:26px;background:#111;color:#fff;font:inherit;font-size:14px;font-weight:600;letter-spacing:.01em;cursor:pointer;box-shadow:0 10px 30px rgba(17,17,17,.28),0 2px 6px rgba(17,17,17,.18);transition:transform .2s ease,box-shadow .2s ease,background .2s ease}
.wbfab__btn:hover{transform:translateY(-2px);box-shadow:0 14px 34px rgba(17,17,17,.32),0 2px 6px rgba(17,17,17,.18)}
.wbfab__btn-open,.wbfab__btn-close{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:rgba(255,255,255,.14);transition:opacity .2s ease,transform .25s ease}
.wbfab__btn-close{position:absolute;left:16px;opacity:0;transform:rotate(-90deg)}
.wbfab.is-open .wbfab__btn-open{opacity:0;transform:rotate(90deg)}
.wbfab.is-open .wbfab__btn-close{opacity:1;transform:none}
.wbfab__panel{width:280px;padding:18px 14px 14px;border-radius:22px;background:rgba(255,255,255,.98);backdrop-filter:saturate(180%) blur(16px);-webkit-backdrop-filter:saturate(180%) blur(16px);box-shadow:0 24px 60px rgba(0,0,0,.18),0 0 0 1px rgba(0,0,0,.05);opacity:0;visibility:hidden;transform:translateY(10px) scale(.98);transform-origin:bottom right;transition:opacity .22s ease,transform .22s ease,visibility .22s}
.wbfab.is-open .wbfab__panel{opacity:1;visibility:visible;transform:none}
@media (hover:hover) and (min-width:750px){.wbfab:hover .wbfab__panel{opacity:1;visibility:visible;transform:none}}
.wbfab__head{margin:0 6px 10px;font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#86868b}
.wbfab__list{list-style:none;margin:0;padding:0;display:grid;gap:2px}
.wbfab__item{display:flex;align-items:center;gap:12px;padding:8px;border-radius:14px;color:#1d1d1f;font-size:15px;font-weight:500;transition:background .15s ease}
.wbfab__item:hover,.wbfab__item:focus-visible{background:#f5f5f7}
.wbfab__tile{display:grid;place-items:center;flex:0 0 36px;width:36px;height:36px;border-radius:11px;color:var(--c);background:color-mix(in srgb,var(--c) 13%,#fff);overflow:hidden}
.wbfab__tile img{width:100%;height:100%;object-fit:cover}
.wbfab__tile.has-logo{background:#fff;box-shadow:inset 0 0 0 1px rgba(0,0,0,.08)}
.wbfab__tile .wbfab__logo{width:26px;height:26px;border-radius:7px;object-fit:contain}
.wbfab__name{flex:1}
.wbfab__go{color:#86868b;opacity:0;transform:translate(-4px,4px);transition:opacity .15s ease,transform .15s ease}
.wbfab__item:hover .wbfab__go,.wbfab__item:focus-visible .wbfab__go{opacity:1;transform:none;color:var(--c)}
.wbfab__chat{display:flex;align-items:center;gap:12px;margin-top:12px;padding:12px 14px;border-radius:16px;background:var(--a);color:#fff;transition:filter .15s ease,transform .15s ease}
.wbfab__chat:hover{filter:brightness(1.08);transform:translateY(-1px)}
.wbfab__chat-text{display:flex;flex-direction:column;line-height:1.25}
.wbfab__chat-text strong{font-size:15px}
.wbfab__chat-text small{font-size:12px;opacity:.8}
@media (max-width:749px){
  .wbfab{right:14px;bottom:calc(14px + env(safe-area-inset-bottom))}
  .wbfab__btn{height:48px;font-size:13px;padding:0 18px 0 12px}
  .wbfab__btn-close{left:12px}
  .wbfab__panel{width:min(300px,calc(100vw - 28px))}
}
@media (prefers-reduced-motion:reduce){.wbfab *{transition:none!important}}

